trace.response_text:
{
  "claims": [
    {
      "claim": "Tenofovir, the closest free-acid phosphonate analog (adenine plus an isopropyloxymethylphosphonate), has low absolute oral bioavailability in preclinical studies and very low Caco-2 permeability (~0.1 × 10^-6 cm/s) consistent with paracellular, not transcellular, absorption. Only ester prodrugs such as tenofovir disoproxil fumarate raise bioavailability to ~25% in the fasted state. Because the query is the corresponding unmasked phosphonic acid, this evidence supports F < 20%.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 13"
      ],
      "record_ids": [
        "Record 13-1",
        "Record 13-3",
        "Record 13-15",
        "Record 13-17",
        "Record 13-21"
      ]
    },
    {
      "claim": "Adefovir dipivoxil, the ester prodrug of the query, was required to increase ileal transport of adefovir by ~10-fold compared with the parent phosphonate; even with this masking the human fasted bioavailability of the delivered adefovir was only about 30%. The query itself, as the free phosphonic acid, is expected to be absorbed far less than this prodrug.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 11"
      ],
      "record_ids": [
        "Record 11-1",
        "Record 11-6"
      ]
    },
    {
      "claim": "In mice, diverse diester prodrugs of a close adenine phosphonate analog yielded absolute oral bioavailability values for the active phosphonate that were usually 0–10%, with only optimized prodrugs reaching 22–26%. Since the query is not an ester prodrug, these prodrug data are upper-bound estimates and support a fail prediction for the free acid.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 12"
      ],
      "record_ids": [
        "Record 12-1",
        "Record 12-12",
        "Record 12-13",
        "Record 12-16"
      ]
    },
    {
      "claim": "Several structurally related adenine analogs without an ionized phosphonate, or delivered as phosphate forms, reach or exceed the 20% threshold in humans: acyclovir F≈20%, didanosine fasting F=22–28%, and fludarabine monophosphate F≈70%. This shows the adenine scaffold is not intrinsically non-absorbable, but these compounds lack the free phosphonic acid that is the main absorption liability of the query.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 1",
        "Molecule 3",
        "Molecule 6"
      ],
      "record_ids": [
        "Record 1-1",
        "Record 3-1",
        "Record 3-2",
        "Record 6-1"
      ]
    }
  ],
  "final_prediction": "fail"
}

